import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem71 protege identidade operação e idempotência',()=>{for(const [id,titulo] of [['e2xjzhLqo2TSHdOKUEaB','Deo Colônia Natura Hoje Masculino 100ml'],['E4L1IqNlovRGggmaVOHW','Principia Kit Essencial Gl-03 + Ch + Vc + Ps Sensível Dia/noite']]){const p={id,titulo,preco:'preservado',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,titulo:'Outro produto',comentario:'manter'}).comentario,'manter');assert.doesNotMatch(x.pros,/ideal|sofistica|hipoalerg|FPS 60|eficácia/i);}});
